import { gsap } from 'gsap';
import {
  uv,
  vec2,
  vec3,
  color,
  mix,
  smoothstep,
  sin,
  fract,
  dot,
  float,
} from 'three/tsl';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, BoxGeometry, DirectionalLight, PointLight } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'journal-card-1';

  // ---- dimensions (aspect matches source rect 512x320 = 1.6:1) ----
  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const cardDepth = 0.06;

  const disposables = [];

  // ---- card body: engineered gradient + subtle static grain ----
  const cardGeo = new BoxGeometry(cardWidth, cardHeight, cardDepth, 1, 1, 1);
  disposables.push(cardGeo);

  const cardMat = new MeshStandardNodeMaterial();
  cardMat.roughness = 0.55;
  cardMat.metalness = 0.35;
  cardMat.clearcoat = 0.18;

  const uvNode = uv();
  const gradientBase = mix(
    color(colors.surface),
    color(colors.ink),
    smoothstep(float(0.0), float(1.0), uvNode.y)
  );
  // deterministic pseudo-random grain, no time input -> stays static
  const noiseCoord = uvNode.mul(900.0);
  const grainNoise = fract(
    sin(dot(noiseCoord, vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grain = grainNoise.sub(0.5).mul(0.035);
  cardMat.colorNode = gradientBase.add(vec3(grain, grain, grain));
  disposables.push(cardMat);

  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.castShadow = false;
  group.add(cardMesh);

  // ---- image inset (bevel-like frame effect via smaller inset plane) ----
  const insetW = cardWidth * 0.92;
  const insetH = cardHeight * 0.9;
  const imgGeo = new PlaneGeometry(insetW, insetH);
  disposables.push(imgGeo);

  const imgMat = new MeshBasicNodeMaterial();
  imgMat.transparent = true;
  disposables.push(imgMat);

  const imgMesh = new THREE.Mesh(imgGeo, imgMat);
  imgMesh.position.z = cardDepth / 2 + 0.002;
  group.add(imgMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  // ---- accent edge bar (kept under 10% of frame) ----
  const accentGeo = new PlaneGeometry(insetW, insetH * 0.06);
  disposables.push(accentGeo);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.colorNode = color(colors.accent);
  disposables.push(accentMat);
  const accentBar = new THREE.Mesh(accentGeo, accentMat);
  accentBar.position.set(0, -insetH / 2 + (insetH * 0.03), cardDepth / 2 + 0.003);
  group.add(accentBar);

  // ---- contact shadow (radial falloff, static) ----
  const shadowRadius = Math.max(cardWidth, cardHeight) * 0.85;
  const shadowGeo = new PlaneGeometry(shadowRadius * 2, shadowRadius * 2);
  disposables.push(shadowGeo);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  const shadowUv = uv().sub(vec2(0.5, 0.5)).mul(2.0);
  const dist = shadowUv.length();
  const falloff = smoothstep(float(1.0), float(0.0), dist);
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = falloff.mul(0.45);
  disposables.push(shadowMat);
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -cardHeight / 2 - 0.01, cardDepth);
  group.add(shadowMesh);

  // ---- local rim + accent lighting (node-local, within intensity caps) ----
  const rim = new DirectionalLight(new THREE.Color(colors.paper), 0.7);
  rim.position.set(-1.2, 0.8, 1.6);
  group.add(rim);

  const accentGlow = new PointLight(new THREE.Color(colors.accent), 0.35, 2.2);
  accentGlow.position.set(0.4, -0.4, 0.8);
  group.add(accentGlow);

  // ---- entrance motion: weighted rise-in settle (single, non-looping) ----
  group.position.y += -0.3;
  group.scale.setScalar(0.98);
  cardMat.opacity = cardMat.opacity ?? 1;
  cardMat.transparent = true;
  cardMat.opacity = 0;
  imgMat.opacity = 0;
  accentMat.opacity = 0;

  const tl = gsap.timeline();
  tl.to(group.position, {
    y: group.position.y + 0.3,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  tl.to([cardMat, imgMat, accentMat], {
    opacity: 1,
    duration: 0.6,
    ease: 'power2.out',
  }, 0.05);
  tl.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.5,
    ease: 'power2.out',
  }, 0.1);
  tl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, 0.55);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    if (imgMat.map && typeof imgMat.map.dispose === 'function') {
      imgMat.map.dispose();
    }
  };

  return group;
}
